/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    schemaProblems
 * depends    —
 * used by    —
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
/**
 * The part of JSON Schema the tool output schemas use, and no more.
 *
 * The server promises a client that `structuredContent` conforms to the tool's `outputSchema`, and
 * the official clients hold it to that: a successful result that does not fit is thrown away and
 * reported as a failed call. So the stdio loop checks each answer before it leaves, and the tests
 * check with the same code. A validator library would do it, and would be a second dependency of
 * a package whose one dependency is `zod`; the schemas use six keywords, so this reads those six
 * and throws on any other, rather than passing a schema it does not understand.
 */

const KEYWORDS = new Set(['type', 'description', 'properties', 'required', 'items', 'enum'])

/** Where to stop: a list of every wrong row in a table of thousands helps nobody. */
const MOST_PROBLEMS = 20

const typeOf = value => (Array.isArray(value) ? 'array' : value === null ? 'null' : typeof value)

const fits = (type, value) => (type === 'integer' ? Number.isInteger(value) : typeOf(value) === type)

/** Every way `value` fails `schema`, as `path: reason`, up to twenty. Empty means it conforms. */
export function schemaProblems(schema, value, at = '$', problems = []) {
  const unread = Object.keys(schema).filter(keyword => !KEYWORDS.has(keyword))
  if (unread.length > 0) throw new Error(`${at}: this checker does not read ${unread.join(', ')}`)
  if (problems.length >= MOST_PROBLEMS) return problems

  if (schema.type !== undefined) {
    const allowed = Array.isArray(schema.type) ? schema.type : [schema.type]
    if (!allowed.some(type => fits(type, value))) {
      problems.push(`${at}: expected ${allowed.join(' | ')}, got ${typeOf(value)}`)
      return problems
    }
  }
  if (schema.enum && !schema.enum.some(option => option === value)) {
    problems.push(`${at}: ${JSON.stringify(value)} is not one of ${JSON.stringify(schema.enum)}`)
  }
  if (typeOf(value) === 'object') {
    for (const key of schema.required ?? []) {
      if (!Object.prototype.hasOwnProperty.call(value, key)) problems.push(`${at}: \`${key}\` is required`)
    }
    for (const [key, spec] of Object.entries(schema.properties ?? {})) {
      if (Object.prototype.hasOwnProperty.call(value, key)) schemaProblems(spec, value[key], `${at}.${key}`, problems)
    }
  }
  if (Array.isArray(value) && schema.items) {
    for (let index = 0; index < value.length && problems.length < MOST_PROBLEMS; index += 1) {
      schemaProblems(schema.items, value[index], `${at}[${index}]`, problems)
    }
  }
  return problems
}
